#!/usr/bin/env python3
"""One-time LEGAL PRO maintenance + bounded pull-deploy bootstrap. Dry-run by default."""
import argparse
import ast
import base64
import datetime as dt
import grp
import hashlib
import json
import os
from pathlib import Path
import pwd
import re
import shutil
import stat
import subprocess
import sys
import tempfile
import time

HTML_B64 = ""
RUNNER_B64 = ""
USER = "legal-pro-deploy"
STATE = Path("/var/lib/legal-pro-deploy")
MAINT = Path("/var/www/legal-pro-maintenance")
RUNNER = Path("/usr/local/lib/legal-pro-deploy/runner.py")
CONFIG = Path("/etc/legal-pro-deploy.json")
UNIT = Path("/etc/systemd/system/legal-pro-deploy.service")
TIMER = Path("/etc/systemd/system/legal-pro-deploy.timer")
SOURCE = "https://api.github.com/repos/777LegalPro/legal-pro-maintenance/contents/deploy.json?ref=production"
BLOCK = '''# LEGAL-PRO-MAINTENANCE-BEGIN v1
    error_page 503 =503 /__lp_maintenance.html;
    location = /__lp_maintenance.html {
        internal;
        alias /var/www/legal-pro-maintenance/maintenance.html;
        charset utf-8;
        default_type text/html;
        open_file_cache off;
        add_header Cache-Control "no-store, max-age=0" always;
        add_header Retry-After "3600" always;
    }
    # LEGAL-PRO-MAINTENANCE-END v1
    '''
GUARD = '''
        # LEGAL-PRO-MAINTENANCE-GUARD v1
        if (-f /var/www/legal-pro-maintenance/enabled) { return 503; }
        open_file_cache off;
'''

def require(ok, message):
    if not ok:
        raise RuntimeError(message)

def run(argv, check=True, timeout=180):
    result = subprocess.run(argv, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=timeout)
    if check and result.returncode:
        raise RuntimeError(" ".join(argv[:3]) + ": " + result.stderr.decode(errors="replace")[-1800:])
    return result

def meta(path):
    s = path.lstat()
    return {"mode": stat.S_IMODE(s.st_mode), "uid": s.st_uid, "gid": s.st_gid}

def snapshot(path):
    if not path.exists() and not path.is_symlink():
        return None
    require(path.is_file() and not path.is_symlink(), "Expected regular file: " + str(path))
    return {**meta(path), "data": base64.b64encode(path.read_bytes()).decode()}

def atomic(path, data, info=None):
    info = info or {"mode": 0o644, "uid": 0, "gid": 0}
    fd, name = tempfile.mkstemp(prefix=".lp-install-", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(data)
            stream.flush()
            os.fchown(stream.fileno(), info["uid"], info["gid"])
            os.fchmod(stream.fileno(), info["mode"])
            os.fsync(stream.fileno())
        os.replace(name, path)
        directory = os.open(path.parent, os.O_RDONLY | os.O_DIRECTORY)
        try:
            os.fsync(directory)
        finally:
            os.close(directory)
    finally:
        if os.path.exists(name):
            os.unlink(name)

def restore(path, saved):
    if saved is None:
        if path.exists() or path.is_symlink():
            path.unlink()
    else:
        atomic(path, base64.b64decode(saved["data"]), saved)

def document(path, value):
    atomic(path, (json.dumps(value, ensure_ascii=False, indent=2) + "\n").encode(),
           {"mode": 0o600, "uid": 0, "gid": 0})

def close_brace(text, opening):
    depth, quote, escape, comment = 0, None, False, False
    for i in range(opening, len(text)):
        ch = text[i]
        if comment:
            comment = ch != "\n"
            continue
        if escape:
            escape = False
            continue
        if quote:
            if ch == "\\": escape = True
            elif ch == quote: quote = None
            continue
        if ch in ("'", '"'): quote = ch
        elif ch == "#": comment = True
        elif ch == "{": depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0: return i
    raise RuntimeError("Unbalanced nginx configuration")

def patch_nginx(text):
    servers = list(re.finditer(r"(?m)^\s*server\s*\{", text))
    require(len(servers) == 2, "Expected exactly two server blocks")
    start = text.index("{", servers[0].start())
    end = close_brace(text, start)
    first = text[start:end + 1]
    require(re.search(r"\bserver_name\s+prolg\.ru\s+www\.prolg\.ru\s*;", first), "Unexpected server names")
    require(re.search(r"\blisten\s+443\b", first), "First server is not the HTTPS server")
    anchors = list(re.finditer(r"(?m)^([ \t]*)location\s+/\s*\{", text))
    require(len(anchors) == 1 and start < anchors[0].start() < end, "Expected one TLS location /")
    anchor = anchors[0]
    loc_open = text.index("{", anchor.start())
    loc_end = close_brace(text, loc_open)
    require(len(re.findall(r"\bproxy_pass\s+http://127\.0\.0\.1:4177\s*;", text[loc_open:loc_end])) == 1,
            "Expected the existing Python proxy on port 4177")
    if "LEGAL-PRO-MAINTENANCE-" in text:
        require(text.count(BLOCK) == text.count(GUARD) == 1, "Different or partial maintenance patch already exists")
        return text
    require(len(re.findall(r"(?m)^\s*location\b", text)) == 1, "Unexpected additional nginx locations")
    indent = anchor.group(1)
    return text[:anchor.start()] + indent + BLOCK + text[anchor.start():loc_open + 1] + GUARD + text[loc_open + 1:]

def public_directories(dist):
    result = []
    for current, dirs, _ in os.walk(dist, followlinks=False):
        dirs[:] = sorted(d for d in dirs if not d.startswith(".") and d.lower() != "admin"
                         and not (Path(current) / d).is_symlink())
        path = Path(current)
        s = path.lstat()
        require(stat.S_ISDIR(s.st_mode), "Directory changed: " + str(path))
        result.append({"path": str(path), **meta(path), "dev": s.st_dev, "ino": s.st_ino})
    return result

def install_deployer(dist, backup):
    try:
        account = pwd.getpwnam(USER)
    except KeyError:
        run(["useradd", "--system", "--user-group", "--home-dir", str(STATE), "--shell", "/usr/sbin/nologin", USER])
        account = pwd.getpwnam(USER)
    group = grp.getgrnam(USER)
    require(account.pw_uid != 0 and group.gr_gid != 0 and account.pw_gid == group.gr_gid and
            account.pw_dir == str(STATE) and account.pw_shell in ("/usr/sbin/nologin", "/sbin/nologin"),
            "Existing deployment account does not match the dedicated service account")
    previous = {str(p): snapshot(p) for p in (RUNNER, CONFIG, UNIT, TIMER)}
    dirs = public_directories(dist)
    document(backup / "deployer-prior-files.json", previous)
    document(backup / "directory-permissions.json", dirs)
    for path in (STATE, RUNNER.parent):
        require(not path.is_symlink() and (not path.exists() or path.is_dir()), "Unsafe service directory")
        path.mkdir(parents=True, exist_ok=True)
    os.chown(STATE, account.pw_uid, group.gr_gid)
    STATE.chmod(0o700)
    os.chown(RUNNER.parent, 0, 0)
    RUNNER.parent.chmod(0o755)
    os.chown(MAINT, 0, group.gr_gid)
    MAINT.chmod(0o2775)
    require(Path("/opt/legal-pro/current/dist").resolve() == dist, "Current release changed")
    for entry in dirs:
        path = Path(entry["path"])
        s = path.lstat()
        require(stat.S_ISDIR(s.st_mode) and (s.st_dev, s.st_ino) == (entry["dev"], entry["ino"]), "Directory changed")
        if s.st_gid != group.gr_gid: os.chown(path, -1, group.gr_gid, follow_symlinks=False)
        if stat.S_IMODE(s.st_mode) != (entry["mode"] | 0o2070): path.chmod(entry["mode"] | 0o2070)
    atomic(RUNNER, base64.b64decode(RUNNER_B64, validate=True))
    cfg = {"manifest_url": SOURCE, "dist": str(dist), "state_dir": str(STATE), "maintenance_dir": str(MAINT)}
    atomic(CONFIG, (json.dumps(cfg, indent=2) + "\n").encode())
    service = f'''[Unit]
Description=LEGAL PRO bounded public-file deployment
Wants=network-online.target
After=network-online.target
[Service]
Type=oneshot
User={USER}
Group={USER}
ExecStart=/usr/bin/python3 {RUNNER} --config {CONFIG}
Environment=PYTHONUNBUFFERED=1
ProtectSystem=strict
ProtectHome=true
PrivateTmp=true
PrivateDevices=true
NoNewPrivileges=true
RestrictSUIDSGID=true
CapabilityBoundingSet=
RestrictAddressFamilies=AF_INET AF_INET6 AF_UNIX
UMask=0022
ReadWritePaths={dist} {STATE} {MAINT}
InaccessiblePaths=-{dist}/admin
MemoryMax=192M
TimeoutStartSec=120
'''
    timer = '''[Unit]
Description=Poll LEGAL PRO production deployment manifest
[Timer]
OnBootSec=1min
OnUnitInactiveSec=120s
AccuracySec=5s
RandomizedDelaySec=5s
Unit=legal-pro-deploy.service
[Install]
WantedBy=timers.target
'''
    atomic(UNIT, service.encode())
    atomic(TIMER, timer.encode())
    run(["systemctl", "daemon-reload"])
    run(["systemctl", "enable", "--now", "legal-pro-deploy.timer"])
    run(["systemctl", "start", "legal-pro-deploy.service"])
    run(["systemctl", "is-active", "--quiet", "legal-pro-deploy.timer"])
    print(run(["systemctl", "show", "legal-pro-deploy.service", "-p", "Result", "-p", "ExecMainStatus"]).stdout.decode().strip())

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--apply", action="store_true")
    args = parser.parse_args()
    require(os.geteuid() == 0, "Run this installer as root")
    html = base64.b64decode(HTML_B64, validate=True)
    runner = base64.b64decode(RUNNER_B64, validate=True)
    require(b"<html" in html.lower() and b"777@prolg.ru" in html and len(html) < 1024 * 1024, "Invalid maintenance HTML")
    html.decode("utf-8")
    ast.parse(runner.decode("utf-8"))
    target = Path("/etc/nginx/sites-enabled/prolg.ru.conf").resolve(strict=True)
    saved_config = snapshot(target)
    original = base64.b64decode(saved_config["data"])
    patched = patch_nginx(original.decode("utf-8")).encode("utf-8")
    dist = Path("/opt/legal-pro/current/dist").resolve(strict=True)
    require(dist.is_dir() and dist.is_relative_to("/opt/legal-pro") and dist.name == "dist", "Unexpected dist")
    require(not re.search(r"\s", str(dist)), "Whitespace in dist path is unsupported")
    require(not MAINT.is_symlink() and (not MAINT.exists() or MAINT.is_dir()), "Unsafe maintenance directory")
    prior_dir = meta(MAINT) if MAINT.exists() else None
    prior = {name: snapshot(MAINT / name) for name in ("maintenance.html", "enabled")}
    run(["nginx", "-t"])
    print(f"VALIDATED: nginx={target}; dist={dist}; HTML SHA256={hashlib.sha256(html).hexdigest()}", flush=True)
    if not args.apply:
        print("DRY RUN: enable full-site 503; install bounded production pull service and 120-second timer. No files written.")
        return
    stamp = dt.datetime.now(dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    backup = Path(tempfile.mkdtemp(prefix="legal-pro-deploy-install-" + stamp + "-", dir="/var/backups"))
    atomic(backup / "nginx.conf", original, {"mode": 0o600, "uid": 0, "gid": 0})
    document(backup / "prior.json", {"nginx_path": str(target), "nginx": saved_config, "maintenance_dir": prior_dir, "maintenance": prior})
    print("INSTALL BACKUP: " + str(backup), flush=True)
    try:
        MAINT.mkdir(parents=True, exist_ok=True, mode=0o755)
        atomic(MAINT / "maintenance.html", html)
        atomic(MAINT / "enabled", b"enabled\n")
        require(target.read_bytes() == original, "Nginx configuration changed concurrently")
        atomic(target, patched, saved_config)
        run(["nginx", "-t"])
        run(["systemctl", "reload", "nginx"])
        deadline = time.monotonic() + 10
        expected_sha = hashlib.sha256(html).hexdigest()
        last = "no HTTP response yet"
        for route in ("/", "/thanks/", "/anything-path", "/assets/app.js"):
            while True:
                remaining = deadline - time.monotonic()
                require(remaining > .1, "Maintenance verification failed within 10s: " + last)
                output = backup / "check-body"
                output.unlink(missing_ok=True)
                try:
                    response = run(["curl", "--silent", "--show-error", "--noproxy", "*", "--max-time",
                                    f"{min(2, remaining - .05):.3f}", "--resolve", "prolg.ru:443:127.0.0.1",
                                    "--output", str(output), "--write-out", "%{http_code}", "https://prolg.ru" + route],
                                   check=False, timeout=min(3, remaining))
                    code, rc = response.stdout.decode(errors="replace").strip(), str(response.returncode)
                except subprocess.TimeoutExpired:
                    code, rc = "000", "timeout"
                body = output.read_bytes() if output.exists() else b""
                actual_sha = hashlib.sha256(body).hexdigest()
                last = f"{route}; HTTP={code or 'empty'}; curl={rc}; body_sha256={actual_sha}; expected_sha256={expected_sha}"
                if rc == "0" and code == "503" and body == html:
                    break
                remaining = deadline - time.monotonic()
                require(remaining > .1, "Maintenance verification failed within 10s: " + last)
                time.sleep(min(1, remaining))
        print("MAINTENANCE VERIFIED: 4 routes, HTTP 503, exact standalone HTML", flush=True)
    except BaseException:
        atomic(target, original, saved_config)
        for name, value in prior.items(): restore(MAINT / name, value)
        if prior_dir:
            os.chown(MAINT, prior_dir["uid"], prior_dir["gid"])
            MAINT.chmod(prior_dir["mode"])
        else:
            try: MAINT.rmdir()
            except OSError: pass
        run(["nginx", "-t"])
        run(["systemctl", "reload", "nginx"])
        print("MAINTENANCE FAILED: original nginx and maintenance files restored", file=sys.stderr)
        raise
    try:
        install_deployer(dist, backup)
        require((MAINT / "enabled").is_file(), "Deployment unexpectedly disabled maintenance")
        print("COMPLETE: full-site maintenance active; production pull service and timer installed", flush=True)
    except BaseException:
        run(["systemctl", "disable", "--now", "legal-pro-deploy.timer"], check=False)
        run(["systemctl", "stop", "legal-pro-deploy.service"], check=False)
        atomic(MAINT / "maintenance.html", html)
        atomic(MAINT / "enabled", b"enabled\n")
        print("DEPLOYER INCOMPLETE: full-site maintenance remains active; backup=" + str(backup), file=sys.stderr)
        raise

if __name__ == "__main__":
    try:
        main()
    except (Exception, KeyboardInterrupt) as error:
        print("ERROR: " + str(error), file=sys.stderr)
        sys.exit(1)
